add(60,'用户启动参数栈未对齐，RV64首次C调用违反ABI','Medium','Confirmed',[(L,[155,164,172,176,180,181,192]),('navy-apps/libs/libos/src/crt0/start.S',[29,30])], 'psABI v1.0 Integer Calling Convention：C入口sp须16字节对齐；uintptr_t自然对齐8；本地crt直接sp=a0。','字符串后直接压数组及argc，无padding；cp->GPRx直接交给_start设置sp。','当前pal+--skip得到sp%16=8；nterm单参数总长度11也导致非8字节对齐；合法argv即触发。','loader-alignment.log sp=7fffffc8；补充nterm+--skip在loader.c:181由UBSan报告8字节未对齐。','预算后插入padding，保证argc和指针表8对齐且交给C的sp16对齐；保留argv/envp解析布局。')
add(61,'exec参数没有32KB用户栈和内核VLA容量限制','Medium','Robustness',[(L,[142,144,153,155,156,162,164,165,177])], '本地STACK_SIZE及映射仅32KB；strlen转换/向下减法和栈VLA必须落在已分配区域。','argc/envc无上界，字符串长度转int，VLA消耗内核栈；无sp下界检查，USTACK_TO_PA把越界VA换成邻接PA。','大参数/未终止指针数组可破坏内核或其他页；当前固定init参数很小。未强加完整ARG_MAX/POSIX。','loader-args-large.log：40000字节参数仍status0，sp=7fff6390低于7fff8000；此fixture内相邻global可写，ASan未报错，不将其写成sanitizer发现。','先有界计数/测长和checked总预算；拒绝超容量参数后再分配/替换地址空间。')
add(62,'new_page不检查堆末端和乘法溢出','High','Confirmed',[(M,[12,13,14,15,20,21])], 'AM heap为[start,end)；讲义允许不回收不等于允许越过物理堆。','new_page共享malloc游标有利于避免重叠，但未检查roundup、页数乘法、end或失败；下游无失败处理。','多进程ELF、brk、反复exec正常分配累计耗尽后越界；NPC默认32KB甚至不能满足4个32KB用户栈。','mm-pages.log游标0x4000越过0x3000；mm-wrap.log页数乘法wrap为0仍返回地址。','checked对齐/乘法/容量，失败不移动游标；loader/VME/brk传播失败或明确受控停止。')
add(63,'brk增长可跨用户栈和用户地址上界且始终成功','High','Confirmed',[(M,[33,34,35,36,38,40,43]),(S,[68])], 'AM user area和loader用户栈不能被heap增长覆盖；SYS_brk本地以0成功/非0失败供_sbrk消费。','只比较max_brk，没有heap上界/用户栈保留检查；ROUNDUP可溢出，最终总返回0；不校验分配。','用户大brk可重映射用户栈或共享内核域；失败仍令libos program_break前进。','mm-brk.log：从7fffe000增长到80001000，maps3含80000000，return0。','保留程序堆下/上限与栈边界；checked round，分配失败返回错误并保留原break。')
add(64,'fd未经范围验证直接索引文件和偏移数组','Medium','Robustness',[(F,[97,114,131,139,140]),(S,[125,126,127,128])], '固定表下标简化只覆盖有效fd；任何数组索引仍需在[0,filenum)内。','read/write/lseek/close均直接用用户fd，负数和过大值导致OOB；零len也先取索引。','open失败返回-1后继续读，或任意坏fd使内核越界；不是要求实现每进程打开表。','fs-device-bad-fd.log：read(-1,buf,0)触发heap-buffer-overflow。','公共入口验证fd范围，错误不修改offset；保持已定sfs简化。')
add(65,'lseek接受文件范围外位置且错误值已改变offset','Medium','Confirmed',[(F,[129,131,132,133,136]),('nanos-lite/include/fs.h',[10])], 'ics2024 §3.4明确sfs定位不越文件边界；newlib off_t在RV64为signed long。','size_t接收负offset，赋long回转后仍修改状态；SET/CUR/END未检查结果负数/越界/溢出；invalid whence倒是原样返回-1。','SEEK_SET(-1)返回-1但留下-1；超过文件size正位置返回成功。合法END负偏移在当前GNU LP64可工作，不能仅因size_t签名全判错。','fs-device-seek.log：negative_seek=-1后read0；past_end_seek=295965而文件size295964。','按signed off_t checked计算候选位置，验证边界后提交；失败保留旧offset。')
add(66,'事件读忽略len并额外写NUL，短缓冲越界','Medium','Confirmed',[(D,[31,54,55,56,57,58])], 'read(fd,buf,len)目的区由len限定；Navy事件协议为kd/ku KEY换行。','strcpy/strcat直接写整个事件和NUL；len0/短缓冲没有拦截，keycode也未验证表范围/非NULL。','正常AM_KEY_A配合法read长度1就越界；坏keycode只列上游异常健壮性，当前正常键范围不据此判坏。','fs-device-events-small.log ASan；events正常打印kd A。','先格式化到有界暂存，按明确事件短读/不足策略返回，绝不写超过len；校验键码。')
add(67,'音频状态读取即使len为零也写4字节','Medium','Robustness',[(D,[95,99,100,101,102])], 'Navy sbctl标准调用提供一个int；除此之外read长度仍应被安全处理，不可覆写短对象。','计算截断len后没有使用，始终*(int*)buf并返回sizeof(int)，可能未对齐。','正常NDL提供4字节是安全路径；零/短/未对齐缓冲为协议边缘风险。','audio-zero.log len0 result4 wrote64；audio-small.log ASan。','要求len>=4且对齐安全或用memcpy限长；错误/不足的返回语义明确且不越界。')
